<?php
if(!defined('ABSPATH'))exit;
final class MGD_WordPress_MCP_Admin{
 private static $instance=null;public static function instance(){if(null===self::$instance)self::$instance=new self();return self::$instance;}
 private function __construct(){add_action('admin_menu',array($this,'menu'));add_action('admin_init',array($this,'settings'));add_action('admin_enqueue_scripts',array($this,'assets'));add_action('admin_post_mgd_wpmcp_set_profile',array($this,'set_profile'));add_filter('plugin_action_links_'.MGD_WPMCP_BASENAME,array($this,'action_links'));add_filter('plugin_row_meta',array($this,'row_meta'),10,2);}
 public function menu(){add_management_page('MGD WordPress MCP','MGD WordPress MCP','manage_options','mgd-wordpress-mcp',array($this,'render'));}
 public function settings(){register_setting('mgd_wordpress_mcp',MGD_WordPress_MCP::OPTION_SETTINGS,array('type'=>'array','sanitize_callback'=>array($this,'sanitize'),'default'=>MGD_WordPress_MCP::defaults()));}
 public function sanitize($input){$d=MGD_WordPress_MCP::defaults();$c=array();foreach(array('writes_enabled','maintenance_enabled','divi_writes_enabled','media_imports_enabled','github_updates','audit_enabled') as $k)$c[$k]=!empty($input[$k]);$c['max_upload_mb']=max(1,min(64,absint($input['max_upload_mb']??$d['max_upload_mb'])));$c['security_profile']=in_array(($input['security_profile']??''),array('read_only','content_editor','admin'),true)?$input['security_profile']:'read_only';$c['rate_limit_per_minute']=max(10,min(600,absint($input['rate_limit_per_minute']??$d['rate_limit_per_minute'])));return $c;}
 public function set_profile(){if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');check_admin_referer('mgd_wpmcp_set_profile');$p=sanitize_key(wp_unslash($_POST['profile']??''));if(in_array($p,array('read_only','content_editor','admin'),true)){MGD_WordPress_MCP_Security::apply_profile($p);}wp_safe_redirect(admin_url('tools.php?page=mgd-wordpress-mcp&tab=settings&profile_saved=1#profiles'));exit;}
 public function assets($hook){if('tools_page_mgd-wordpress-mcp'!==$hook&&'plugins.php'!==$hook)return;wp_enqueue_style('mgd-wordpress-mcp-admin',MGD_WPMCP_URL.'assets/admin.css',array(),MGD_WPMCP_VERSION);}
 public function action_links($links){array_unshift($links,'<a href="'.esc_url(admin_url('tools.php?page=mgd-wordpress-mcp&tab=wizard')).'">Einrichten</a>');return $links;}
 public function row_meta($links,$file){if(MGD_WPMCP_BASENAME!==$file)return $links;$details=add_query_arg(array('tab'=>'plugin-information','plugin'=>'mgd-wordpress-mcp','TB_iframe'=>'true','width'=>'772','height'=>'650'),self_admin_url('plugin-install.php'));$links[]='<a href="'.esc_url($details).'" class="thickbox open-plugin-details-modal">Details ansehen</a>';$links[]='<a href="'.esc_url(admin_url('tools.php?page=mgd-wordpress-mcp&tab=about')).'">Über & Impressum</a>';$links[]='<a href="https://Michael-Gahn.de" target="_blank" rel="noopener noreferrer">Michael-Gahn.de</a>';$links[]='<a href="https://github.com/MichaelGahnDESIGN/MGD_WordPress-MCP" target="_blank" rel="noopener noreferrer">GitHub</a>';$links[]='<a href="https://github.com/MichaelGahnDESIGN/MGD_WordPress-MCP/tree/main/wiki" target="_blank" rel="noopener noreferrer">Wiki & Dokumentation</a>';return $links;}
 private function adapter_version(){require_once ABSPATH.'wp-admin/includes/plugin.php';foreach(get_plugins() as $data)if('MCP Adapter'===$data['Name'])return $data['Version'];return '';}
 private function nav($tab,$base){$tabs=array('status'=>'Übersicht','wizard'=>'Einrichtungs-Assistent','settings'=>'Sicherheit & Freigaben','connection'=>'Verbindung','audit'=>'Audit-Log','about'=>'Über das Plugin');echo '<nav class="nav-tab-wrapper">';foreach($tabs as $k=>$l)echo '<a class="nav-tab '.($k===$tab?'nav-tab-active':'').'" href="'.esc_url(add_query_arg('tab',$k,$base)).'">'.esc_html($l).'</a>';echo '</nav>';}
 private function checkbox($k,$l,$d,$s){?><label class="mgd-wpmcp-toggle"><input type="checkbox" name="<?php echo esc_attr(MGD_WordPress_MCP::OPTION_SETTINGS);?>[<?php echo esc_attr($k);?>]" value="1" <?php checked(!empty($s[$k]));?>><span><strong><?php echo esc_html($l);?></strong><small><?php echo esc_html($d);?></small></span></label><?php}
 private function render_profiles($current){$profiles=array('read_only'=>array('Nur lesen','Website untersuchen und Inhalte lesen. Keine Änderungen.','Empfohlen zum Start'),'content_editor'=>array('Inhalte bearbeiten','Beiträge, Seiten, Medien, SEO und freigegebene Builder-Funktionen.','Für Redaktion & Design'),'admin'=>array('Administration','Zusätzlich Backups, Wartung und Updates mit zusätzlichen Bestätigungen.','Für erfahrene Administratoren'));echo '<div id="profiles" class="mgd-wpmcp-profile-grid">';foreach($profiles as $key=>$p){?><form class="mgd-wpmcp-profile <?php echo $current===$key?'is-active':'';?>" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mgd_wpmcp_set_profile"><input type="hidden" name="profile" value="<?php echo esc_attr($key);?>"><?php wp_nonce_field('mgd_wpmcp_set_profile');?><span class="mgd-wpmcp-profile-check"><?php echo $current===$key?'✓':'○';?></span><strong><?php echo esc_html($p[0]);?></strong><small><?php echo esc_html($p[1]);?></small><em><?php echo esc_html($p[2]);?></em><button class="button <?php echo $current===$key?'':'button-secondary';?>" type="submit" <?php disabled($current,$key);?>><?php echo $current===$key?'Aktiv':'Auswählen';?></button></form><?php}echo '</div>';}
 public function render(){if(!current_user_can('manage_options'))return;$s=MGD_WordPress_MCP::get_settings();$tab=sanitize_key(wp_unslash($_GET['tab']??'status'));if('help'===$tab)$tab='connection';$base=admin_url('tools.php?page=mgd-wordpress-mcp');$env=MGD_WordPress_MCP_Environment::summary();?><div class="wrap mgd-wpmcp-wrap"><header class="mgd-wpmcp-hero"><div class="mgd-wpmcp-kicker">WORDPRESS MEETS AI · MICHAEL GAHN DESIGN</div><h1>MGD WordPress MCP</h1><p>Die sichere Verbindung zwischen deiner WordPress-Website und KI-Agenten wie Claude Code, Codex und anderen MCP-Clients.</p><div class="mgd-wpmcp-badges"><span class="mgd-wpmcp-badge is-red">v<?php echo esc_html(MGD_WPMCP_VERSION);?></span><span class="mgd-wpmcp-badge is-ok">Aktiv</span><span class="mgd-wpmcp-badge"><?php echo esc_html(MGD_WordPress_MCP_Security::profile_label());?></span></div></header><?php $this->nav($tab,$base);
 if('wizard'===$tab){MGD_WordPress_MCP_Wizard::render();}
 elseif('settings'===$tab){?><section class="mgd-wpmcp-card"><h2>Sicherheitsprofil</h2><p>Beginne mit einem Profil. Darunter kannst du die einzelnen Rechte weiterhin fein einstellen.</p><?php $this->render_profiles(MGD_WordPress_MCP_Security::profile());?></section><form method="post" action="options.php" class="mgd-wpmcp-card"><?php settings_fields('mgd_wordpress_mcp');?><input type="hidden" name="<?php echo esc_attr(MGD_WordPress_MCP::OPTION_SETTINGS);?>[security_profile]" value="<?php echo esc_attr(MGD_WordPress_MCP_Security::profile());?>"><h2>Feineinstellungen</h2><?php $this->checkbox('writes_enabled','Schreibzugriff','Beiträge, Seiten, Medien und SEO-Daten erstellen oder ändern.',$s);$this->checkbox('divi_writes_enabled','Divi-5-Schreibzugriff','Divi-Inhalte kontrolliert ändern.',$s);$this->checkbox('media_imports_enabled','Externe Medienimporte','Medien von ausdrücklich angegebenen HTTPS-URLs importieren.',$s);$this->checkbox('maintenance_enabled','Wartung & Updates','Backups und Einzelupdates nach zusätzlicher Bestätigung.',$s);$this->checkbox('audit_enabled','Audit-Log','Agenten-Aktionen lokal nachvollziehen.',$s);$this->checkbox('github_updates','Plugin-Updates über GitHub','Nur zur Versionsprüfung des Plugins.',$s);?><label class="mgd-wpmcp-field"><strong>Rate Limit pro Minute</strong><input type="number" min="10" max="600" name="<?php echo esc_attr(MGD_WordPress_MCP::OPTION_SETTINGS);?>[rate_limit_per_minute]" value="<?php echo esc_attr($s['rate_limit_per_minute']);?>"><small>Schützt den MCP-Endpunkt vor versehentlichen Request-Schleifen.</small></label><?php submit_button('Feineinstellungen speichern');?></form><?php}
 elseif('connection'===$tab){$doctor=MGD_WordPress_MCP_Doctor::run();?><section class="mgd-wpmcp-card"><div class="mgd-wpmcp-section-head"><span class="mgd-wpmcp-step">✓</span><div><h2>Connection Doctor</h2><p>Prüft die technische Bereitschaft deiner WordPress-Installation. Es werden keine Zugangsdaten übertragen.</p></div></div><div class="mgd-wpmcp-doctor-score <?php echo $doctor['ready']?'is-ready':'is-warning';?>"><strong><?php echo esc_html($doctor['summary']);?></strong><span><?php echo esc_html($doctor['passed'].' von '.$doctor['total'].' Prüfungen erfolgreich');?></span></div><div class="mgd-wpmcp-doctor-list"><?php foreach($doctor['checks'] as $c):?><div class="mgd-wpmcp-doctor-row"><span class="mgd-wpmcp-ready-dot"><?php echo $c['ok']?'✓':'!';?></span><span><strong><?php echo esc_html($c['label']);?></strong><small><?php echo esc_html($c['detail']);?></small></span></div><?php endforeach;?></div><p><a class="button button-primary" href="<?php echo esc_url(add_query_arg(array('page'=>'mgd-wordpress-mcp','tab'=>'connection','doctor'=>time()),admin_url('tools.php')));?>">Erneut prüfen</a></p></section><section class="mgd-wpmcp-card"><h2>Dein MCP-Endpunkt</h2><div class="mgd-wpmcp-endpoint"><code><?php echo esc_html(MGD_WordPress_MCP::adapter_endpoint_url());?></code></div><p>Profil: <strong><?php echo esc_html(MGD_WordPress_MCP_Security::profile_label());?></strong></p></section><section class="mgd-wpmcp-card"><h2>Client Setup Generator</h2><p>Wähle deinen Client und kopiere die Konfiguration. Secrets werden bewusst nicht ausgefüllt.</p><div class="mgd-wpmcp-client-grid"><?php foreach(array('claude_code'=>'Claude Code','codex'=>'Codex','cursor'=>'Cursor / VS Code','generic'=>'Generischer MCP Client') as $k=>$l):$cfg=MGD_WordPress_MCP_Client_Setup::config($k);?><details class="mgd-wpmcp-client"><summary><?php echo esc_html($l);?><span>anzeigen</span></summary><pre><code><?php echo esc_html($cfg['config']);?></code></pre><p><?php echo esc_html($cfg['note']);?></p></details><?php endforeach;?></div><p><a class="button button-primary" href="<?php echo esc_url(admin_url('profile.php#application-passwords-section'));?>">Application Password erstellen</a></p></section><?php}
 elseif('audit'===$tab){$entries=MGD_WordPress_MCP_Audit::latest(100);?><div class="mgd-wpmcp-card"><h2>Audit-Log</h2><p>Technische Agenten-Aktionen. Secrets werden nicht absichtlich protokolliert.</p><div class="mgd-wpmcp-table-wrap"><table class="widefat striped"><thead><tr><th>Zeit</th><th>Benutzer</th><th>Ability</th><th>Risiko</th><th>Status</th><th>Zusammenfassung</th></tr></thead><tbody><?php if(!$entries)echo '<tr><td colspan="6">Noch keine Einträge.</td></tr>';foreach($entries as $e)echo '<tr><td>'.esc_html($e['created_at']).'</td><td>'.esc_html($e['user_id']).'</td><td><code>'.esc_html($e['ability']).'</code></td><td>'.esc_html($e['risk']).'</td><td>'.($e['success']?'✓':'✕').'</td><td>'.esc_html($e['summary']).'</td></tr>';?></tbody></table></div></div><?php}
 elseif('about'===$tab){?><div class="mgd-wpmcp-card"><h2>Über MGD WordPress MCP</h2><p>Kostenloses Open-Source-Projekt von Michael Gahn DESIGN für kontrollierte WordPress-Automation mit modernen KI-Agenten.</p><h3>Privacy by Default</h3><p>Keine externen Fonts, Icon-CDNs, JavaScript-CDNs, Telemetrie oder Werbung in der Admin-Oberfläche.</p><h3>Impressum gemäß § 5 DDG</h3><p><strong>Michael Gahn DESIGN</strong><br>Inhaber: Michael Gahn<br>Dr.-Theodor-Brugsch-Str. 12<br>08529 Plauen<br>Deutschland</p><p>Telefon: +49 (0) 151 59156639<br>E-Mail: Anfrage@Michael-Gahn.de<br>USt-IdNr.: DE288143343<br>Steuernummer: 223/222/02451</p></div><?php}
 else{$doctor=MGD_WordPress_MCP_Doctor::run();?><div class="mgd-wpmcp-features"><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">↗</div><h3>KI-Agent verbinden</h3><p><?php echo esc_html($doctor['summary']);?></p><a href="<?php echo esc_url(add_query_arg('tab','connection',$base));?>">Verbindung prüfen →</a></article><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">▱</div><h3>Builder & Plugins</h3><p><?php echo esc_html($env['builder']['label']);?> erkannt.</p><a href="<?php echo esc_url(add_query_arg('tab','wizard',$base));?>">Einrichtung →</a></article><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">◇</div><h3><?php echo esc_html(MGD_WordPress_MCP_Security::profile_label());?></h3><p>Aktuelles Sicherheitsprofil.</p><a href="<?php echo esc_url(add_query_arg('tab','settings',$base));?>">Profil ändern →</a></article><article class="mgd-wpmcp-feature"><div class="mgd-wpmcp-icon">✦</div><h3>Audit & Kontrolle</h3><p>Aktionen nachvollziehen und sensible Funktionen begrenzen.</p><a href="<?php echo esc_url(add_query_arg('tab','audit',$base));?>">Audit-Log →</a></article></div><div class="mgd-wpmcp-grid"><section class="mgd-wpmcp-card"><h2>Dein MCP-Endpunkt</h2><div class="mgd-wpmcp-endpoint"><code><?php echo esc_html(MGD_WordPress_MCP::adapter_endpoint_url());?></code></div></section><section class="mgd-wpmcp-card"><h2>Systemstatus</h2><ul class="mgd-wpmcp-status-list"><li><span>WordPress</span><strong><?php echo esc_html(get_bloginfo('version'));?></strong></li><li><span>PHP</